'use strict';
const test=require('node:test');
const assert=require('node:assert/strict');
const S=require('./review_state.js');
test('navigation round-trip retains filters, location, disclosure, and paused audio position',()=>{const state={...S.defaults,view:'samples',meeting:'meeting-a',group:'group/a',query:'voice + room',page:4,sample:'sample-a',open:['meeting-a'],details:['sample-a'],audio:'sample:sample-a',time:12.3,scroll:901,noise:true,groupStatus:'unnamed'};assert.deepEqual(S.parse(S.serialize(state)),state);});
test('malformed URL values use valid bounded state',()=>{const s=S.parse('?view=unknown&method=other&page=-9&time=Infinity&scroll=NaN&noise=anything');assert.equal(s.view,'compare');assert.equal(s.method,'other');assert.equal(S.reconcileMethod(s,['global_dbscan_full']).method,'global_dbscan_full');assert.equal(s.page,0);assert.equal(s.time,0);assert.equal(s.scroll,0);assert.equal(s.noise,false);});
test('representative listening avoids physical aliases and favors other meetings',()=>{const rows=[{sample_id:'a',meeting_id:'m1',start:0,source:'system',support_spans:[{start:0,end:3}]},{sample_id:'alias',meeting_id:'m1',start:0,source:'system',support_spans:[{start:0,end:3}]},{sample_id:'b',meeting_id:'m1',start:4,source:'system',support_spans:[{start:4,end:7}]},{sample_id:'c',meeting_id:'m2',start:0,source:'system',support_spans:[{start:0,end:3}]},{sample_id:'d',meeting_id:'m3',start:0,source:'system',support_spans:[{start:0,end:3}]}];assert.deepEqual(S.representatives(rows).map(s=>s.sample_id),['a','c','d']);});
test('group names apply without thousands of sample writes; explicit sample exceptions survive rename and undo',()=>{const f=S.ensureFeedback({reviews:{sample:{person:'Example B',personOverride:true}},notes:''});assert.equal(S.nameGroup(f,'method','group','Example A'),true);assert.deepEqual(S.effectivePerson(f,'method','group','other'),{person:'Example A',scope:'group'});assert.equal(S.effectivePerson(f,'method','group','sample').person,'Example B');S.nameGroup(f,'method','group','Example C');S.undoGroup(f);assert.equal(S.groupPerson(f,'method','group'),'Example A');assert.equal(f.reviews.sample.person,'Example B');assert.equal(Object.keys(f.reviews).length,1);});
test('empty explicit sample decision clears inheritance; reverting it restores group name',()=>{const f=S.ensureFeedback({reviews:{},notes:''});S.nameGroup(f,'m','g','Example A');f.reviews.s={person:'',personOverride:true};assert.deepEqual(S.effectivePerson(f,'m','g','s'),{person:'',scope:'sample'});delete f.reviews.s.personOverride;assert.deepEqual(S.effectivePerson(f,'m','g','s'),{person:'Example A',scope:'group'});});
test('clear and undo restores group without changing previous sample feedback',()=>{const f=S.ensureFeedback({reviews:{s:{verdict:'mixed',notes:'Example exception'}},notes:''});S.nameGroup(f,'m','g','Example A');S.nameGroup(f,'m','g','');assert.equal(S.groupPerson(f,'m','g'),'');S.undoGroup(f);assert.equal(S.groupPerson(f,'m','g'),'Example A');assert.deepEqual(f.reviews.s,{verdict:'mixed',notes:'Example exception'});});
test('naming is isolated between method outputs',()=>{const f=S.ensureFeedback({});S.nameGroup(f,'m1','g','Example A');assert.equal(S.groupPerson(f,'m2','g'),'');});
test('new playback cancels pending owner and stale completions stay invalid',()=>{const owner=S.playbackOwner(),events=[],a={stop:()=>events.push('stop a')},b={stop:()=>events.push('stop b')};const first=owner.claim(a);assert.equal(owner.active(a,first),true);const next=owner.claim(b);assert.deepEqual(events,['stop a']);assert.equal(owner.active(a,first),false);assert.equal(owner.active(b,next),true);owner.invalidate();assert.deepEqual(events,['stop a','stop b']);assert.equal(owner.active(b,next),false);});
test('clean stale tab cannot replace another dirty draft; different dirty edits remain exportable',()=>{const entries=new Map(),storage={getItem:k=>entries.get(k)||null,setItem:(k,v)=>entries.set(k,v)};const a={sessionID:'a',updatedAt:1,dirty:true,feedback:{notes:'First edits'},formDrafts:{group:'Unapplied name'}};S.storeDraft(storage,'dataset',a);const clean={sessionID:'b',updatedAt:2,dirty:false,feedback:{notes:''},formDrafts:{}};assert.equal(S.storeDraft(storage,'dataset',clean),false);assert.equal(JSON.parse(entries.get('dataset')).feedback.notes,'First edits');S.storeDraft(storage,'dataset',{...clean,dirty:true,feedback:{notes:'Second edits'}});assert.equal(JSON.parse(entries.get('dataset:recovered:1:a')).formDrafts.group,'Unapplied name');assert.equal(JSON.parse(entries.get('dataset')).feedback.notes,'Second edits');});
test('paused restoration permits position updates without reviving another owner',()=>{const owner=S.playbackOwner(),a={stop(){}},b={stop(){}};assert.equal(owner.available(a),true);owner.claim(b);assert.equal(owner.available(a),false);assert.equal(owner.available(b),true);});
test('paused audio restoration survives early zero positions and retries unknown metadata duration',()=>{const restore=S.mediaRestoration(5.4),media={readyState:0,currentTime:0,duration:NaN,seeking:false};assert.equal(restore.pending(),true);assert.equal(restore.apply(media),false);media.readyState=1;assert.equal(restore.apply(media),false);assert.equal(restore.pending(),true);media.duration=9;media.seeking=true;assert.equal(restore.apply(media),false);assert.equal(media.currentTime,5.4);assert.equal(restore.pending(),true);media.currentTime=0;assert.equal(restore.finish(media),false);assert.equal(restore.apply(media),false);media.seeking=false;assert.equal(restore.finish(media),true);assert.equal(restore.pending(),false);assert.equal(media.currentTime,5.4);});
test('restoration clamps a saved position after changed audio duration and waits for actual seek completion',()=>{const restore=S.mediaRestoration(12),media={readyState:4,currentTime:0,duration:3,seeking:true};restore.apply(media);assert.equal(media.currentTime,2.95);assert.equal(restore.pending(),true);media.seeking=false;assert.equal(restore.finish(media),true);});
test('restoration waits for a real seekable range before issuing a seek',()=>{const restore=S.mediaRestoration(5.4);let end=0;const media={readyState:4,currentTime:0,duration:9,seeking:false,seekable:{length:1,start:()=>0,end:()=>end}};assert.equal(restore.apply(media),false);assert.equal(media.currentTime,0);assert.equal(restore.pending(),true);end=9;assert.equal(restore.apply(media),true);assert.equal(media.currentTime,5.4);assert.equal(restore.pending(),false);});
test('method switching preserves recording playback while history navigation restores paused',()=>{const old={view:'transcript',meeting:'m1',track:'all',method:'global_dbscan'};assert.equal(S.preserveTranscriptPlayback(old,{...old,method:'current_local_library'}),true);assert.equal(S.preserveTranscriptPlayback(old,{...old,row:'another-row'}),true);assert.equal(S.preserveTranscriptPlayback(old,old,true),false);assert.equal(S.preserveTranscriptPlayback(old,{...old,meeting:'m2'}),false);assert.equal(S.preserveTranscriptPlayback(old,{...old,view:'groups'}),false);});
test('track changes preserve timeline position using original track ordinals and recorded offsets',()=>{const receipt={audio_tracks:[{index:0,recording_offset:0},{index:2,recording_offset:4.5}]};assert.equal(S.timelineTime(10,2,receipt),14.5);assert.equal(S.recordingTime(14.5,'all',receipt),14.5);assert.equal(S.recordingTime(14.5,2,receipt),10);assert.equal(S.recordingTime(2,2,receipt),0);});
test('transcript identity requires full compatible evidence and keeps partial or mixed passages unresolved',()=>{const row={start:10,end:20,track_index:0,recording_key:'m/0',coverage_intervals:[{sample_id:'a',start:10,end:15},{sample_id:'b',start:15,end:20}]},f=S.ensureFeedback({}),assign={a:{group:'g',person_id:'p1',state:'automatic'},b:{group:'g',person_id:'p1',state:'confirmed'}};assert.equal(S.transcriptAssociation(row,'m',assign,f).person_id,'p1');assert.equal(S.transcriptAssociation({...row,coverage_intervals:[row.coverage_intervals[0]]},'m',assign,f).kind,'partial');assert.equal(S.transcriptAssociation(row,'m',{...assign,b:{group:'g2',person_id:'p2',state:'automatic'}},f).kind,'mixed');assert.equal(S.transcriptAssociation(row,'m',{...assign,b:{...assign.b,state:'excluded'}},f).kind,'partial');});
test('method judgments remain separate from shared passage correction and sample feedback',()=>{const f=S.ensureFeedback({reviews:{sample:{person:'Example Sample'}}});S.judgeTranscript(f,'method-a','row','wrong');S.judgeTranscript(f,'method-b','row','correct');S.correctTranscript(f,'row','Example Person');assert.equal(f.transcriptReviews['method-a'].row.verdict,'wrong');assert.equal(f.transcriptReviews['method-b'].row.verdict,'correct');assert.equal(f.transcriptCorrections.row.person,'Example Person');assert.equal(f.reviews.sample.person,'Example Sample');});
test('passage judgments retain the judged prediction and detect later simulated name changes',()=>{const f=S.ensureFeedback({}),old={kind:'person',name:'Example A',simulated:true};S.judgeTranscript(f,'m','row','correct',old);old.name='Example B';assert.equal(f.transcriptReviews.m.row.prediction.name,'Example A');assert.equal(S.samePrediction(f.transcriptReviews.m.row.prediction,old),false);assert.equal(S.samePrediction(f.transcriptReviews.m.row.prediction,{kind:'person',name:'Example A',simulated:true}),true);});

test('partial transcript evidence exposes selected method group or name without assigning whole passage',()=>{const row={start:0,end:10,track_index:0,recording_key:'m/0',coverage_intervals:[{sample_id:'s',start:2,end:6}]},f=S.ensureFeedback({});const a=S.transcriptAssociation(row,'a',{s:{group:'global-a'}},f),b=S.transcriptAssociation(row,'b',{s:{group:'global-b'}},f);assert.equal(a.kind,'partial');assert.equal(a.coverage,.4);assert.equal(a.evidence.group,'global-a');assert.equal(b.evidence.group,'global-b');S.nameGroup(f,'a','global-a','Example Person');assert.equal(S.transcriptAssociation(row,'a',{s:{group:'global-a'}},f).evidence.name,'Example Person');assert.equal(S.transcriptAssociation(row,'a',{s:{group:'noise-s',noise:true}},f).evidence.kind,'unknown');});
test('current catalog is required and old method URLs normalize to its first candidate',()=>{assert.deepEqual(S.selectedMethods({methods:{global_dbscan_unique:{}}}),[]);const available=['current_local_library','model_a'];assert.equal(S.reconcileMethod({...S.defaults,method:'global_dbscan_unique',group:'old',page:3},available).method,'model_a');assert.equal(S.reconcileMethod({...S.defaults,method:'global_dbscan_unique',group:'old'},available).group,'');});
test('undo leaves hidden legacy decisions intact while undoing the latest visible naming decision',()=>{const f=S.ensureFeedback({});S.nameGroup(f,'global_dbscan_full','new-group','Example New');S.nameGroup(f,'legacy-method','old-group','Example Old');const op=S.undoGroup(f,['current_local_library','global_dbscan_full']);assert.equal(op.method,'global_dbscan_full');assert.equal(S.groupPerson(f,'legacy-method','old-group'),'Example Old');assert.equal(f.simulation.history.length,1);});
test('current saved transcript preserves local labels and only displays person assignments with full passage scope',()=>{const row={local_label:'source|sys_01',saved_person_id:'p1',saved_person_coverage:'partial',association_uncertain:true};assert.deepEqual(S.savedTranscriptAssociation(row),{kind:'local',label:'source|sys_01',saved:true,uncertain:true,reason:'Saved person identity covers part of this passage'});const full=S.savedTranscriptAssociation({...row,saved_person_coverage:'full'});assert.equal(full.kind,'person');assert.equal(full.person_id,'p1');assert.equal(full.uncertain,true);});
test('saved tentative person suggestions retain their tier and differ from automatic identity evidence',()=>{const row={saved_person_id:'p1',saved_person_coverage:'full',saved_person_tier:'tentative',association_uncertain:false};const tentative=S.savedTranscriptAssociation(row);assert.equal(tentative.kind,'person');assert.equal(tentative.tier,'tentative');assert.equal(tentative.tentative,true);assert.equal(tentative.reason,'Saved tentative person suggestion');const automatic=S.savedTranscriptAssociation({...row,saved_person_tier:'automatic'});assert.equal(automatic.tentative,false);assert.equal(automatic.tier,'automatic');assert.equal(S.samePrediction(tentative,automatic),false);const partial=S.savedTranscriptAssociation({...row,local_label:'sys_01',saved_person_coverage:'partial'});assert.equal(partial.kind,'local');assert.equal(partial.tentative,true);assert.equal(partial.label,'sys_01');});
test('current transcript simulation appears only for explicit overlapping group or sample names',()=>{const row={start:0,end:10,track_index:0,recording_key:'m/0',coverage_intervals:[{sample_id:'s',start:0,end:10}]},assign={s:{group:'g',person_id:'saved-person',state:'automatic'}},f=S.ensureFeedback({});assert.equal(S.transcriptSimulation(row,'current',assign,f),null);S.nameGroup(f,'current','g','Example Group');assert.equal(S.transcriptSimulation(row,'current',assign,f).name,'Example Group');f.reviews.s={person:'Example Exception',personOverride:true};assert.equal(S.transcriptSimulation(row,'current',assign,f).name,'Example Exception');assert.equal(S.transcriptSimulation({...row,coverage_intervals:[{sample_id:'s',start:10,end:12}]},'current',assign,f),null);assert.equal(S.transcriptSimulation(row,'current',{s:{...assign.s,state:'excluded'}},f),null);});
test('current naming preview retains partial scope while observed saved transcript identity stays unchanged',()=>{const row={start:0,end:10,track_index:0,recording_key:'m/0',saved_person_id:'saved-person',saved_person_coverage:'full',coverage_intervals:[{sample_id:'s',start:2,end:6}]},assign={s:{group:'g',person_id:'saved-person',state:'automatic'}},f=S.ensureFeedback({});const before=S.savedTranscriptAssociation(row);S.nameGroup(f,'current','g','Example Preview');const preview=S.transcriptSimulation(row,'current',assign,f);assert.equal(preview.kind,'partial');assert.equal(preview.coverage,.4);assert.equal(preview.evidence.name,'Example Preview');assert.deepEqual(S.savedTranscriptAssociation(row),before);assert.equal(before.person_id,'saved-person');});

const modelResults={methods:{global_dbscan_wespeaker:{},global_dbscan_redimnet_b6:{},current_local_library:{},legacy:{}},method_catalog:[{id:'global_dbscan_wespeaker',label:'Example WeSpeaker',default_variant:'s080_m3',variants:[{id:'s080_m3',path:'variants/global_dbscan_wespeaker/s080_m3.json'},{id:'s085_m5',path:'variants/global_dbscan_wespeaker/s085_m5.json'},{id:'s035_m3',status:'skipped'}]},{id:'global_dbscan_redimnet_b6',label:'Example ReDimNet',default_variant:'s080_m3',variants:[{id:'s080_m3',path:'variants/global_dbscan_redimnet_b6/s080_m3.json'}]},{id:'current_local_library',variants:[]}]};
test('catalog exposes each declared model while excluding legacy methods',()=>{assert.deepEqual(S.selectedMethods(modelResults),['global_dbscan_wespeaker','global_dbscan_redimnet_b6','current_local_library']);});
test('dynamic model and variant URL state survives reload and history with playback intact',()=>{const state={...S.defaults,view:'transcript',method:'global_dbscan_redimnet_b6',variant:'s085_m5',meeting:'example',row:'row-a',track:0,audio:'recording:example:0',time:43.2,transcriptScroll:310};assert.deepEqual(S.parse(S.serialize(state)),state);assert.equal(S.preserveTranscriptPlayback(state,{...state,method:'global_dbscan_wespeaker',variant:'s080_m3'}),true);assert.equal(S.preserveTranscriptPlayback(state,state,true),false);});
test('variant reconciliation uses catalog defaults and rejects skipped or unknown settings',()=>{const state={...S.defaults,method:'global_dbscan_wespeaker',variant:'s085_m5',group:'g',page:3};assert.equal(S.variantSelection(modelResults,state).id,'s085_m5');assert.deepEqual(S.reconcileVariant(modelResults,state),state);for(const variant of ['unknown','s035_m3']){const result=S.reconcileVariant(modelResults,{...state,variant});assert.equal(result.variant,'');assert.equal(result.group,'');assert.equal(result.page,0);}assert.equal(S.reconcileVariant(modelResults,{...state,method:'current_local_library'}).variant,'');});
test('variant loader prevents stale success and failure after rapid selection, cancellation and retry',async()=>{const requests=[],loader=S.variantLoader((key,signal)=>new Promise((resolve,reject)=>requests.push({key,signal,resolve,reject})));const first=loader.request('a/one'),second=loader.request('b/two');assert.equal(requests[0].signal.aborted,true);requests[1].resolve({variant:'two'});assert.deepEqual(await second,{current:true,value:{variant:'two'}});requests[0].resolve({variant:'one'});assert.equal((await first).current,false);const third=loader.request('a/three');loader.cancel();requests[2].reject(Error('stale failure'));assert.equal((await third).current,false);const failed=loader.request('a/retry');requests[3].reject(Error('unavailable'));await assert.rejects(failed,/unavailable/);const retry=loader.request('a/retry');requests[4].resolve({variant:'retry'});assert.equal((await retry).current,true);});
test('judged predictions retain model setting and detect an otherwise identical alternate setting',()=>{const feedback=S.ensureFeedback({}),prediction={kind:'group',group:'same-members',variant:'s080_m3'};S.judgeTranscript(feedback,'global_dbscan_wespeaker','row','correct',prediction);assert.equal(S.samePrediction(feedback.transcriptReviews.global_dbscan_wespeaker.row.prediction,{...prediction,variant:'s085_m5'}),false);assert.equal(feedback.transcriptReviews.global_dbscan_wespeaker.row.prediction.variant,'s080_m3');});

test('full speech comparisons follow receipts and model catalog rather than one legacy method ID',()=>{assert.equal(S.isFullSpeech(modelResults),true);assert.equal(S.isFullSpeech({full_speech:{complete:true},methods:{global_dbscan_redimnet_b6:{}}}),true);assert.equal(S.isFullSpeech({metadata:{input_metadata:{full_speech:{windows:2}}}}),true);assert.equal(S.isFullSpeech({methods:{global_dbscan_unique:{}}}),false);});
const pairFixture={version:1,configs:[{id:'one',label:'Example One',primary:true},{id:'two',label:'Example Two',primary:true},{id:'ablation',label:'Example Ablation',primary:false}],pairs:[{id:'p1',sample_ids:['b','a'],selection:'disagreement',predictions:{one:'same',two:'different',ablation:'omitted'}},{id:'p2',sample_ids:['b','c'],selection:'control',predictions:{one:'different',two:'unresolved',ablation:'same'}}]};
test('pair navigation and audio position round-trip independently of transcript state',()=>{const value={...S.defaults,view:'compare',pair:'p1',pairFilter:'controls',pairScoreFilter:'control',pairModel:'example',pairAlgorithm:'hdbscan',pairAblations:true,reveal:true,audio:'mix:meeting',time:42.5,pairAudio:'pair:a',pairTime:1.2};assert.deepEqual(S.parse(S.serialize(value)),value);});
test('pair answers are unordered, model-independent and preserve transcript feedback',()=>{const f=S.ensureFeedback({transcriptReviews:{method:{row:{verdict:'correct'}}}}),pair=pairFixture.pairs[0];S.judgePair(f,pair,'same');assert.deepEqual(f.pairReviews.p1,{sample_ids:['a','b'],verdict:'same'});assert.equal(S.pairTruth(f,{...pair,sample_ids:['a','b']}).verdict,'same');assert.equal(f.transcriptReviews.method.row.verdict,'correct');assert.equal(S.judgePair(f,pair,'same'),false);assert.equal(S.pairReview(f,{...pair,sample_ids:['a','c']}),null);});
test('shared person names derive reusable pair truth and explicit uncertainty remains excluded',()=>{const f=S.ensureFeedback({});S.namePair(f,pairFixture.pairs[0],{a:'Example Person',b:' example   PERSON '});assert.equal(S.pairTruth(f,pairFixture.pairs[0]).verdict,'same');assert.equal(S.pairTruth(f,pairFixture.pairs[0]).source,'names');S.namePair(f,pairFixture.pairs[1],{b:'Example Person',c:'Another Person'});assert.equal(S.pairTruth(f,pairFixture.pairs[1]).verdict,'different');for(const verdict of ['unsure','mixed']){S.judgePair(f,pairFixture.pairs[0],verdict);assert.equal(S.pairTruth(f,pairFixture.pairs[0]).verdict,verdict);assert.equal(S.pairTruth(f,pairFixture.pairs[0]).conflict,false);}});
test('direct-answer versus names conflicts are excluded until corrected or cleared',()=>{const f=S.ensureFeedback({}),pair=pairFixture.pairs[0];S.namePair(f,pair,{a:'Example A',b:'Example B'});S.judgePair(f,pair,'same');assert.equal(S.pairTruth(f,pair).conflict,true);let scores=S.scorePairs(pairFixture,f);assert.equal(scores.summary.conflicts,1);assert.equal(scores.rows[0].judged_pairs,0);S.judgePair(f,pair,'');assert.equal(S.pairTruth(f,pair).verdict,'different');assert.equal(S.pairTruth(f,pair).source,'names');});
test('pair decision and shared-name Undo restores prior truth without touching other feedback',()=>{const f=S.ensureFeedback({reviews:{a:{notes:'Example note'}}}),pair=pairFixture.pairs[0];S.judgePair(f,pair,'different');S.namePair(f,pair,{a:'Example',b:'Example'});assert.equal(S.pairTruth(f,pair).conflict,true);assert.equal(S.undoPair(f).kind,'pair-names');assert.equal(S.pairTruth(f,pair).verdict,'different');assert.deepEqual(f.samplePeople,{});S.undoPair(f);assert.equal(S.pairTruth(f,pair).verdict,null);assert.equal(f.reviews.a.notes,'Example note');assert.equal(S.undoPair(f),null);});
test('scoreboard counts false merges, unnecessary splits, unresolved and omissions with explicit denominators',()=>{const f=S.ensureFeedback({});S.judgePair(f,pairFixture.pairs[0],'different');S.judgePair(f,pairFixture.pairs[1],'same');const {rows,summary}=S.scorePairs(pairFixture,f);assert.equal(summary.known_same,1);assert.equal(summary.known_different,1);assert.equal(summary.direct_answers,2);assert.equal(summary.name_derived,0);assert.equal(rows[0].false_merges,1);assert.equal(rows[0].unnecessary_splits,1);assert.equal(rows[0].resolved_pairs,2);assert.equal(rows[0].judged_pairs,2);assert.equal(rows[1].correct_pairs,1);assert.equal(rows[1].unresolved,1);assert.equal(rows[2].omitted,1);assert.equal(rows[2].correct_pairs,1);const controls=S.scorePairs(pairFixture,f,'control');assert.equal(controls.summary.pairs,1);assert.equal(controls.rows[0].known_different,0);});
test('unknown predictions remain omitted rather than becoming false split evidence',()=>{const f=S.ensureFeedback({}),review=structuredClone(pairFixture);S.judgePair(f,review.pairs[0],'same');review.pairs[0].predictions.one='invalid';assert.equal(S.scorePairs(review,f).rows[0].omitted,1);});
test('mixed and unsure judgments stay out of every configuration denominator',()=>{const f=S.ensureFeedback({});S.judgePair(f,pairFixture.pairs[0],'mixed');S.judgePair(f,pairFixture.pairs[1],'unsure');const scores=S.scorePairs(pairFixture,f);assert.equal(scores.summary.mixed,1);assert.equal(scores.summary.unsure,1);assert.ok(scores.rows.every(row=>row.judged_pairs===0&&row.correct_pairs===0));});
test('overlap omissions remain explicit transcript evidence without being called noise',()=>{const f=S.ensureFeedback({}),row={start:0,end:2,track_index:0,recording_key:'example/0',coverage_intervals:[{sample_id:'sample',start:0,end:2}]};const prediction=S.transcriptAssociation(row,'method',{sample:{state:'excluded',fit_role:'overlap_omitted',noise:null}},f);assert.equal(prediction.kind,'omitted');assert.equal(prediction.reason,'Excluded: window overlap');});
test('complete unanimous transcript corrections supply live names without importing or duplicating truth',()=>{const f=S.ensureFeedback({transcriptCorrections:{r1:{person:'Example A'},r2:{person:'example a'},r3:{person:'Example A'}}}),mapping={a:['r1','r2'],b:['r3']},pair=pairFixture.pairs[0];assert.deepEqual(S.samplePerson(f,'a',mapping),{person:'Example A',source:'transcript'});assert.equal(S.pairTruth(f,pair,mapping).verdict,'same');assert.deepEqual(f.samplePeople,{});assert.equal(S.namePair(f,pair,{}),false);f.transcriptCorrections.r3.person='Example B';assert.equal(S.pairTruth(f,pair,mapping).verdict,'different');delete f.transcriptCorrections.r2;assert.equal(S.samplePerson(f,'a',mapping).source,'none');f.transcriptCorrections.r2={person:'Example C'};assert.equal(S.samplePerson(f,'a',mapping).source,'none');});
test('explicit clip names override transcript-derived names and edit only supplied sample fields',()=>{const f=S.ensureFeedback({transcriptCorrections:{r1:{person:'Example A'},r2:{person:'Example A'}}}),mapping={a:['r1'],b:['r2']},pair=pairFixture.pairs[0];S.namePair(f,pair,{a:'Example B'});assert.equal(f.samplePeople.b,undefined);assert.equal(S.pairTruth(f,pair,mapping).verdict,'different');assert.equal(S.samplePerson(f,'a',mapping).source,'sample');S.judgePair(f,pair,'unsure');assert.equal(S.pairTruth(f,pair,mapping).verdict,'unsure');S.undoPair(f);S.undoPair(f);assert.equal(S.pairTruth(f,pair,mapping).verdict,'same');});
test('scoreboard distinguishes direct and live name-derived definitive denominators',()=>{const f=S.ensureFeedback({transcriptCorrections:{r1:{person:'Example'},r2:{person:'Example'}}}),review={...pairFixture,sample_passages:{a:['r1'],b:['r2']}};S.judgePair(f,pairFixture.pairs[1],'different');const scores=S.scorePairs(review,f);assert.equal(scores.summary.direct_scored,1);assert.equal(scores.summary.names_scored,1);assert.equal(scores.summary.known_same,1);assert.equal(scores.summary.known_different,1);assert.equal(scores.rows[0].judged_pairs,2);});
