test("route sections keep cold Compare independent of assignments and transcripts",()=>{assert.deepEqual(S.sectionKeys("compare"),["compare"]);assert.deepEqual(S.sectionKeys("groups"),["evidence"]);assert.deepEqual(S.sectionKeys("transcript"),["evidence","transcripts","details"]);});

function sectionHarness(){const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),source=fs.readFileSync(path.join(__dirname,'review.js'),'utf8'),pending=[],requests=[],context={S,state:{...S.defaults},data:{results:{}},variantLoads:{cancel(){}},variantStatus:{key:'',status:'ready'},stopAudio(){},transcriptBinding:'',view:{replaceChildren(){}},routeShell(){},el(){return {setAttribute(){}};},button(label,parent,action){context.retry=action;},render(){context.renders++;},renders:0,fetch(url,{signal}){requests.push({url,signal});return new Promise((resolve,reject)=>pending.push({resolve:value=>resolve({ok:true,json:async()=>value}),reject}));}};vm.createContext(context);vm.runInContext(source.slice(source.indexOf('const loadedSections='),source.indexOf('function rebuildGroups')).replace(/function routeShell\(\)\{[^\n]+\}\n/,''),context);return {context,pending,requests,run:()=>vm.runInContext('ensureSections({})',context),flush:async()=>{await new Promise(resolve=>setImmediate(resolve));}};}
test('cold Compare requests its listening section without assignments; returning after evidence keeps full samples',async()=>{const h=sectionHarness();assert.equal(h.run(),false);assert.equal(h.requests[0].url,'/section/compare.json');h.pending[0].resolve({samples:[{sample_id:'a'}],results:{pair_review:{pairs:[]}}});await h.flush();assert.equal(h.context.data.samples.length,1);h.context.state.view='groups';h.run();h.pending[1].resolve({samples:[{sample_id:'a'},{sample_id:'b'}]});await h.flush();h.context.state.view='compare';assert.equal(h.run(),true);assert.equal(h.context.data.samples.length,2);assert.equal(h.requests.length,2);});
test('section transitions cancel stale requests and errors retry without losing route or feedback',async()=>{const h=sectionHarness();h.run();h.context.state.view='settings';h.run();assert.equal(h.requests[0].signal.aborted,true);h.pending[0].resolve({results:{pair_review:{stale:true}}});h.pending[1].reject(Error('offline'));await h.flush();assert.equal(h.context.data.results.pair_review,undefined);h.run();assert.equal(typeof h.context.retry,'function');h.context.retry();h.run();h.pending[2].resolve({results:{resources:{ready:true}}});await h.flush();assert.equal(h.context.data.results.resources.ready,true);assert.equal(h.context.state.view,'settings');});
test('initial document applies requested route before main content and keeps saving disabled during bootstrap',()=>{const fs=require('node:fs'),path=require('node:path'),html=fs.readFileSync(path.join(__dirname,'review.html'),'utf8');assert.ok(html.indexOf('document.body.className=')<html.indexOf('<header>'));assert.ok(html.indexOf('button.dataset.view===route')<html.indexOf('<main>'));assert.ok(html.includes('id="save" disabled'));assert.ok(!html.includes('class="intro muted"'));});

test('loading Transcript sections releases a cancelled Voice Groups variant so the same setting can retry',async()=>{const h=sectionHarness();h.context.state={...S.defaults,view:'transcript',method:'global_dbscan_wespeaker'};h.context.data.results=modelResults;h.context.variantStatus={key:'global_dbscan_wespeaker/s080_m3',status:'loading'};h.run();assert.equal(h.context.variantStatus.status,'ready');let started=0;Object.assign(h.context,{loadedVariants:{},variantCache:new Map(),variantKey:()=> 'global_dbscan_wespeaker/s080_m3',rebuildGroups(){},variantLoads:{cancel(){},request(){started++;return new Promise(()=>{});}}});const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),source=fs.readFileSync(path.join(__dirname,'review.js'),'utf8');vm.runInContext(source.slice(source.indexOf('function ensureVariant(){'),source.indexOf('function variantNotice(')),h.context);assert.equal(vm.runInContext('ensureVariant()',h.context),false);assert.equal(started,1);});

const intervalRow={id:'passage',meeting_id:'meeting',recording_key:'recording',track_index:0,start:0,end:10,coverage_intervals:[{sample_id:'a',start:1,end:3},{sample_id:'b',start:3,end:5},{sample_id:'n',start:6,end:8}]};
const intervalAssignments={a:{group:'g1'},b:{group:'g2'},n:{noise:true,group:'noise'}};
test('timed blocks preserve gaps, adjacency, sequential groups, and unclustered evidence',()=>{const blocks=S.transcriptTimeline(intervalRow,'method',intervalAssignments,S.ensureFeedback({}));assert.deepEqual(blocks.map(b=>[b.start,b.end,b.prediction.kind,b.prediction.group||'']),[[0,1,'unsupported',''],[1,3,'group','g1'],[3,5,'group','g2'],[5,6,'unsupported',''],[6,8,'unknown',''],[8,10,'unsupported','']]);assert.equal(blocks.some(b=>b.prediction.kind==='conflict'),false);});
test('timed conflicts require positive overlapping differing assignments; duplicate and adjacent equal assignments coalesce',()=>{const row={...intervalRow,coverage_intervals:[{sample_id:'a',start:0,end:4},{sample_id:'b',start:2,end:6}]},blocks=S.transcriptTimeline(row,'m',intervalAssignments,S.ensureFeedback({}));assert.deepEqual(blocks.map(b=>[b.start,b.end,b.prediction.kind]),[[0,2,'group'],[2,4,'conflict'],[4,6,'group'],[6,10,'unsupported']]);const same={...row,coverage_intervals:[{sample_id:'a',start:0,end:2},{sample_id:'a',start:0,end:2},{sample_id:'a',start:2,end:10}]};assert.deepEqual(S.transcriptTimeline(same,'m',intervalAssignments,{}),[{start:0,end:10,prediction:{kind:'group',group:'g1'}}]);assert.deepEqual(S.transcriptTimeline({...row,coverage_intervals:[...row.coverage_intervals].reverse()},'m',intervalAssignments,{}),blocks);});
