test('reenabling Follow or ending editing synchronizes pages after playback already entered the row',()=>{const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),source=fs.readFileSync(path.join(__dirname,'review.js'),'utf8'),start=source.indexOf('function updateTranscriptPlayer()'),end=source.indexOf('\nfunction playTranscriptRow(',start),row={id:'current',start:10,end:20},rows=[...Array.from({length:150},(_,i)=>({id:'past'+i,start:0,end:1})),row],seek={},times={firstChild:{},lastChild:{}};let refreshes=0,scrolls=0;const context={S,state:{view:'transcript',meeting:'m',track:'all',row:'',follow:false,page:0},transcriptFollowRow:'',lastActiveRow:'',transcriptAudio:{isConnected:true,paused:false,currentTime:12,duration:30,reviewControls:{range:()=>null}},mediaRestorations:new WeakMap(),transcriptHighlights:new WeakMap(),transcriptRows:rows,transcriptDisplayRows:rows,transcriptList:{querySelectorAll:()=>[]},document:{activeElement:null,querySelector:query=>query.includes('input[type=range]')?seek:times,getElementById:()=>({scrollIntoView(){scrolls++;}})},data:{transcripts:{meetings:[]}},meeting:()=>({duration:30}),time:String,writeURL(){},refreshTranscriptRows(){refreshes++;}};vm.runInNewContext(source.slice(start,end),context);context.updateTranscriptPlayer();assert.equal(context.lastActiveRow,'current');assert.equal(context.state.page,0);context.state.follow=true;context.updateTranscriptPlayer();assert.equal(context.state.page,1);assert.equal(refreshes,1);assert.equal(scrolls,1);context.state.page=0;context.document.activeElement={tagName:'INPUT'};context.updateTranscriptPlayer();assert.equal(context.state.page,0);assert.equal(refreshes,1);context.document.activeElement=null;context.updateTranscriptPlayer();assert.equal(context.state.page,1);assert.equal(refreshes,2);assert.equal(scrolls,2);context.updateTranscriptPlayer();assert.equal(refreshes,2);});

test('Follow resumes once for an untimed current row on the same page after disabled follow or editing',()=>{const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),source=fs.readFileSync(path.join(__dirname,'review.js'),'utf8'),start=source.indexOf('function updateTranscriptPlayer()'),end=source.indexOf('\nfunction playTranscriptRow(',start),row={id:'untimed',start:10,end:20},seek={},times={firstChild:{},lastChild:{}};let scrolls=0;const context={S,state:{view:'transcript',meeting:'m',track:'all',row:'',follow:false,page:0},lastActiveRow:'',transcriptFollowRow:'',transcriptAudio:{isConnected:true,paused:false,currentTime:12,duration:30,reviewControls:{range:()=>null}},mediaRestorations:new WeakMap(),transcriptHighlights:new WeakMap(),transcriptRows:[row],transcriptDisplayRows:[row],transcriptList:{querySelectorAll:()=>[]},document:{activeElement:null,querySelector:query=>query.includes('input[type=range]')?seek:times,getElementById:()=>({scrollIntoView(){scrolls++;}})},data:{transcripts:{meetings:[]}},meeting:()=>({duration:30}),time:String,writeURL(){},refreshTranscriptRows(){assert.fail('Same-page Follow must preserve rows');}};vm.runInNewContext(source.slice(start,end),context);context.updateTranscriptPlayer();assert.equal(context.lastActiveRow,'untimed');assert.equal(scrolls,0);context.state.follow=true;context.updateTranscriptPlayer();assert.equal(scrolls,1);context.updateTranscriptPlayer();assert.equal(scrolls,1);context.document.activeElement={tagName:'TEXTAREA'};context.updateTranscriptPlayer();assert.equal(scrolls,1);context.document.activeElement=null;context.updateTranscriptPlayer();assert.equal(scrolls,2);context.updateTranscriptPlayer();assert.equal(scrolls,2);context.state.follow=false;context.updateTranscriptPlayer();context.state.follow=true;context.updateTranscriptPlayer();assert.equal(scrolls,3);});

test('Follow keeps current text and block above the transport together when they fit and prioritizes text for tall passages',()=>{const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),source=fs.readFileSync(path.join(__dirname,'review.js'),'utf8'),start=source.indexOf('function followTranscriptText('),end=source.indexOf('\nfunction playTranscriptRow(',start),scroller={scrollTop:0,getBoundingClientRect:()=>({top:0,bottom:120})},context={document:{querySelector:()=>null},window:{innerHeight:1000},transcriptScroller:scroller,transcriptList:{querySelector:()=>({getBoundingClientRect:()=>({height:20})})}};vm.runInNewContext(source.slice(start,end),context);const positioned=(top,bottom)=>({getBoundingClientRect:()=>({top:top-scroller.scrollTop,bottom:bottom-scroller.scrollTop})}),text=positioned(70,90),block=positioned(130,150);context.followTranscriptText(text,block);assert.equal(scroller.scrollTop,38);assert.ok(text.getBoundingClientRect().top>=28);assert.ok(block.getBoundingClientRect().bottom<=112);context.followTranscriptText(text,block);assert.equal(scroller.scrollTop,38);scroller.scrollTop=0;const distant=positioned(200,240);context.followTranscriptText(text,distant);assert.equal(scroller.scrollTop,0);context.followTranscriptText(text,distant);assert.equal(scroller.scrollTop,0);context.followTranscriptText(block);assert.equal(scroller.scrollTop,38);assert.ok(block.getBoundingClientRect().bottom<=112);});

test('Follow clips its viewport above the fixed transport and the browser edge',()=>{const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),source=fs.readFileSync(path.join(__dirname,'review.js'),'utf8'),start=source.indexOf('function followTranscriptText('),end=source.indexOf('\nfunction playTranscriptRow(',start),scroller={scrollTop:0,getBoundingClientRect:()=>({top:428.5,bottom:862})},transport={hidden:false,getBoundingClientRect:()=>({top:728,bottom:816})},context={document:{querySelector:()=>transport},window:{innerHeight:900},transcriptScroller:scroller,transcriptList:{querySelector:()=>({getBoundingClientRect:()=>({height:69.5})})}};vm.runInNewContext(source.slice(start,end),context);const positioned=(top,bottom)=>({getBoundingClientRect:()=>({top:top-scroller.scrollTop,bottom:bottom-scroller.scrollTop})}),text=positioned(690,710),block=positioned(804,843);context.followTranscriptText(text,block);assert.equal(scroller.scrollTop,123);assert.ok(text.getBoundingClientRect().top>=506);assert.equal(block.getBoundingClientRect().bottom,720);context.followTranscriptText(text,block);assert.equal(scroller.scrollTop,123);transport.hidden=true;context.window.innerHeight=700;scroller.scrollTop=0;context.followTranscriptText(text,block);assert.equal(scroller.scrollTop,151);assert.equal(block.getBoundingClientRect().bottom,692);});

